import{_ as l,a0 as r,w as p,s as o,ao as d,I as t,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智 | LCTT x X-CMD","titleTemplate":false,"description":"如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted","title":"如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智","tag":"202001","desc":""},"relativePath":"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted.md","filePath":"[post].md"}'),c={name:"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted.md"};function h(u,s,g,k,b,f){const n=r("Link");return p(),o("div",null,[s[15]||(s[15]=d(`<h1 id="如果-ssh-被中斷-linux-screen-工具如何拯救你的任務以及理智" tabindex="-1">如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智 <a class="header-anchor" href="#如果-ssh-被中斷-linux-screen-工具如何拯救你的任務以及理智" aria-label="Permalink to “如果 SSH 被中斷，Linux screen 工具如何拯救你的任務以及理智”">​</a></h1><blockquote><p>當你需要確保長時間運行的任務不會在 SSH 會話中斷時被殺死時，Linux screen 命令可以成為救生員。以下是使用方法。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/09/working_w_screen-shs-100812448-large.jpg" alt=""></p><p>如果因 SSH 會話斷開而不得不重啓一個耗時的進程，那麼你可能會很高興瞭解一個有趣的工具，可以用來避免此問題：<code>screen</code> 工具。</p><p><code>screen</code> 是一個終端多路複用器，它使你可以在單個 SSH 會話中運行多個終端會話，並隨時從它們之中脱離或重新接駁。做到這一點的過程非常簡單，僅涉及少數命令。</p><p>要啓動 <code>screen</code> 會話，只需在 SSH 會話中鍵入 <code>screen</code>。 然後，你可以開始啓動需要長時間運行的進程，並在適當的時候鍵入 <code>Ctrl + A Ctrl + D</code> 從會話中脱離，然後鍵入 <code>screen -r</code> 重新接駁。</p><p>如果你要運行多個 <code>screen</code> 會話，更好的選擇是為每個會話指定一個有意義的名稱，以幫助你記住正在處理的任務。使用這種方法，你可以在啓動每個會話時使用如下命令命名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -S slow-build</span></span></code></pre></div><p>一旦運行了多個會話，要重新接駁到一個會話，需要從列表中選擇它。在以下命令中，我們列出了當前正在運行的會話，然後再重新接駁其中一個。請注意，一開始這兩個會話都被標記為已脱離。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -ls</span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>        6617.check-backups      (09/26/2019 04:35:30 PM)    (Detached)</span></span>
<span class="line"><span>        1946.slow-build         (09/26/2019 02:51:50 PM)    (Detached)</span></span>
<span class="line"><span>2 Sockets in /run/screen/S-shs</span></span></code></pre></div><p>然後，重新接駁到該會話要求你提供分配給會話的名稱。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -r slow-build</span></span></code></pre></div><p>在脱離的會話中，保持運行狀態的進程會繼續進行處理，而你可以執行其他工作。如果你使用這些 <code>screen</code> 會話之一來查詢 <code>screen</code> 會話情況，可以看到當前重新接駁的會話再次顯示為 <code>Attached</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -ls</span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>        6617.check-backups      (09/26/2019 04:35:30 PM)    (Attached)</span></span>
<span class="line"><span>        1946.slow-build         (09/26/2019 02:51:50 PM)    (Detached)</span></span>
<span class="line"><span>2 Sockets in /run/screen/S-shs.</span></span></code></pre></div><p>你可以使用 <code>-version</code> 選項查詢正在運行的 <code>screen</code> 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -version</span></span>
<span class="line"><span>Screen version 4.06.02 (GNU) 23-Oct-17</span></span></code></pre></div><h3 id="安裝-screen" tabindex="-1">安裝 screen <a class="header-anchor" href="#安裝-screen" aria-label="Permalink to “安裝 screen”">​</a></h3><p>如果 <code>which screen</code> 未在屏幕上提供信息，則可能你的系統上未安裝該工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which screen</span></span>
<span class="line"><span>/usr/bin/screen</span></span></code></pre></div><p>如果你需要安裝它，則以下命令之一可能適合你的系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install screen</span></span>
<span class="line"><span>sudo yum install screen</span></span></code></pre></div><p>當你需要運行耗時的進程時，如果你的 SSH 會話由於某種原因斷開連接，則可能會中斷這個耗時的進程，那麼 <code>screen</code> 工具就會派上用場。而且，如你所見，它非常易於使用和管理。</p><p>以下是上面使用的命令的摘要：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -S &lt;process description&gt;      開始會話</span></span>
<span class="line"><span>Ctrl+A Ctrl+D                        從會話中脱離</span></span>
<span class="line"><span>screen -ls                           列出會話</span></span>
<span class="line"><span>screen -r &lt;process description&gt;      重新接駁會話</span></span></code></pre></div><p>儘管還有更多關於 <code>screen</code> 的知識，包括可以在 <code>screen</code> 會話之間進行操作的其他方式，但這已經足夠幫助你開始使用這個便捷的工具了。</p><hr>`,26)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3441777/how-the-linux-screen-tool-can-save-your-tasks-and-your-sanity-if-ssh-is-interrupted.html"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3441777/how-the-linux-screen-tool-can-save-your-tasks-and-your-sanity-if-ssh-is-interrupted.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const x=l(c,[["render",h]]);export{m as __pageData,x as default};
